#!/usr/bin/env node
/**
 * Concatenate shared styles into site.css (one render-blocking request).
 * Edit the part files, then: npm run css
 */
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const STYLES = path.join(ROOT, 'assets', 'styles');
const PARTS = [
  'fonts.css',
  'typography.css',
  'icons.css',
  'tokens.css',
  'style.css',
  'layout.css',
  'i18n.css',
  'footer.css',
  'mobile-chrome.css',
  'chrome-responsive.css',
  'responsive.css',
  'premium.css'
];

const banner = `/**
 * Generated by scripts/bundle-css.js — do not edit.
 * Sources: ${PARTS.join(', ')}
 * Rebuild: npm run css
 */

`;

const body = PARTS.map((name) => {
  const file = path.join(STYLES, name);
  const css = fs.readFileSync(file, 'utf8').replace(/^\uFEFF/, '');
  return `/* === ${name} === */\n${css.trim()}\n`;
}).join('\n');

fs.writeFileSync(path.join(STYLES, 'site.css'), banner + body);
const bytes = Buffer.byteLength(banner + body);
console.log(`Wrote assets/styles/site.css (${PARTS.length} parts, ${bytes} bytes)`);
